import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    a = []
    for _ in range(n):
        a.append(int(next(iterator)))
    b = []
    for _ in range(n):
        b.append(int(next(iterator)))

    # Count frequency of each unique a_i
    count = {}
    for x in a:
        count[x] = count.get(x, 0) + 1

    # Identify "good" values: those that are subsets of at least one other value present in the array
    good_values = set()
    for x in count:
        is_good = False
        for y in count:
            if x == y:
                continue
            # Check if x is a subset of y (i.e., (x & y) == x)
            if (x & y) == x:
                is_good = True
                break
        if is_good:
            good_values.add(x)

    # Calculate maximum sum of b_i for students with "good" a_i
    total_sum = 0
    for i in range(n):
        if a[i] in good_values:
            total_sum += b[i]

    # We need at least two students. If we have less than 2 students with good a_i, output 0.
    # Note: If total_sum > 0, it implies at least one student is included. 
    # We must verify count of included students >= 2.
    included_count = 0
    for i in range(n):
        if a[i] in good_values:
            included_count += 1

    if included_count < 2:
        print(0)
    else:
        print(total_sum)

if __name__ == "__main__":
    solve()
